    35	      let body = bodies.get(batch.requestId);
    36	      if (!body) {
    37	        body = JSON.stringify({ ...batch, changes: batch.changes.map(c => 'value' in c ? { ...c, value: normalizeRecord(c.key, c.value) } : c) });
