    10	/** Runtime storage API. Durable adapters flush retained revisions before publishing bindings. */
    11	export function getDiagramRevision(id: string): DiagramRevision { return diagramRevisions.get(id); }
    12	export function listDiagramRevisions(diagramId: string): readonly DiagramRevisionSummary[] {
    13	  return Object.freeze(diagramRevisions.list(diagramId).map(({ id, diagramId, parentId }) => Object.freeze({ id, diagramId, parentId })));
