    15	export function importDiagramRevision(revision: DiagramRevision): void {
    16	  const refs = diagramContentNodes(revision.diagram.content).map(node => revision.nodeRefs?.[node.id]);
    17	  if (refs.some(ref => typeof ref !== 'string' || !ref) || new Set(refs).size !== refs.length) throw Error('Invalid logical node identities');
    18	  diagramRevisions.register(revision);
    19	}
    20	export function retainDiagramRevision(result: DiagramRevisionResult): DiagramRevisionResult {
    21	  importDiagramRevision(result.revision);
    22	  const revision = getDiagramRevision(result.revision.id);
    23	  return { ...result, diagram: revision.diagram, revision };
    24	}
    25	// Convenience commands for existing synchronous callers; the domain operations above work without this store.
    26	export function createStoredDiagram(input: DiagramInput) { return retainDiagramRevision(createDiagram(input)); }
